from fractions import Fraction


def first_to_appear(a, b):
    """Exact chance that pattern a appears before pattern b, fair coin."""
    nodes = sorted({x[:k] for x in (a, b) for k in range(len(x))}, key=len)
    idx = {s: i for i, s in enumerate(nodes)}
    n = len(nodes)
    half = Fraction(1, 2)
    m = [[Fraction(0)] * (n + 1) for _ in range(n)]
    for s in nodes:
        i = idx[s]
        m[i][i] += 1
        for c in 'HT':
            t = s + c
            if t.endswith(a):
                m[i][n] += half
            elif not t.endswith(b):
                while t not in idx:
                    t = t[1:]
                m[i][idx[t]] -= half
    for c in range(n):
        p = next(r for r in range(c, n) if m[r][c] != 0)
        m[c], m[p] = m[p], m[c]
        pv = m[c][c]
        m[c] = [v / pv for v in m[c]]
        for r in range(n):
            if r != c and m[r][c] != 0:
                f = m[r][c]
                m[r] = [x - f * y for x, y in zip(m[r], m[c])]
    return m[idx['']][n]
